<script setup>
import{ref}from'vue';const focus=ref(-1),hover=ref(null),colors=['#77c9ff','#f0c36e','#f69cab'],labels=['Tag = 1','Recoil category','Topology cut','HCAL total','HCAL max','Final ECAL'],data=[[5794358,4641895,3114535,272207,88871,0],[5794358,138513,138513,8051,2552,0],[5794358,138513,120147,3922,1096,0]];const y=n=>n?275-Math.log10(n)*34:275
</script><template><div class="controls"><button @click="focus=-1">All regions</button><button v-for="i in 3" @click="focus=i-1" :style="{color:colors[i-1]}">SR{{i}}</button><span>{{hover||'Cumulative counts · logarithmic scale'}}</span></div><svg viewBox="0 0 880 340" class="hist"><g v-for="i in 7"><line x1="58" x2="870" :y1="275-i*34" :y2="275-i*34" stroke="#ffffff14"/><text x="12" :y="280-i*34">{{['','10¹','10²','10³','10⁴','10⁵','10⁶','10⁷'][i]}}</text></g><g v-for="(stage,c) in labels"><g v-for="(row,r) in data" :opacity="focus===-1||focus===r?1:.13"><rect v-if="row[c]" :x="88+c*129+r*24" :y="y(row[c])" width="19" :height="275-y(row[c])" :fill="colors[r]" rx="2" tabindex="0" @mouseenter="hover='SR'+(r+1)+' · '+stage+': '+row[c].toLocaleString()" @focus="hover='SR'+(r+1)+' · '+stage+': '+row[c].toLocaleString()" @mouseleave="hover=null"/><text v-else :x="98+c*129+r*24" y="269" text-anchor="middle" :fill="colors[r]">0</text></g><text :x="111+c*129" y="302" text-anchor="middle">{{stage}}</text></g></svg></template><style scoped>.hist{width:100%;height:305px}.hist text{fill:#bdc7d5;font:13px 'DM Sans'}.hist rect{transition:opacity .3s;cursor:pointer}.controls{display:flex;gap:10px;margin-top:12px;font-size:13px}.controls button{border:1px solid #ffffff25;padding:5px 12px;border-radius:4px}.controls span{margin-left:auto;color:#bbc4d0}</style>
